  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.archivedAt === null && member.status === "active";
}

/** Assignees and project leads must be current members of the workspace. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  if (!(await isCurrentMember(orgId, userId))) {
    throw new NotFoundError("Member", userId);
  }
}

export async function assertOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const found = await labelRepo.findLabelsByIdsAnyOrg(labelIds);
  const byId = new Map(found.map((label) => [label.id as string, label]));
  for (const id of labelIds) {
    const label = byId.get(id);
    if (!label) throw new NotFoundError("Label", id);
    assertOrgScope(actor, label.orgId);
    if (label.orgId !== orgId) throw new NotFoundError("Label", id);
  }
}

export async function assertValidParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueByIdAnyOrg(parentId);
  if (!parent) throw new NotFoundError("Issue", parentId);
  assertOrgScope(actor, parent.orgId);
  if (
    parent.orgId !== orgId ||
    parent.projectId !== projectId ||
    parent.archivedAt !== null
  ) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

export async function assertValidReplyParent(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentByIdAnyOrg(parentId);
  if (!parent) throw new NotFoundError("Comment", parentId);
  assertOrgScope(actor, parent.orgId);
  if (
    parent.orgId !== orgId ||
    parent.issueId !== issueId ||
    parent.archivedAt !== null ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

async function listCurrentMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const all: MemberWithUser[] = [];
  let cursor: string | null = null;
  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      limit: MEMBER_PAGE_SIZE,
      cursor,
    } as Parameters<typeof memberRepo.listMembers>[0]);
    all.push(...page.items);
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }
  return all.filter(
    (member) => member.status === "active" && member.archivedAt === null,
  );
}

/**
 * Mentions are silently limited to current members: handles in the body and
 * ids supplied by the composer that are not current members are dropped.
 */
export async function resolveMentionedMembers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await listCurrentMembers(orgId);
  const memberIds = new Set<string>(members.map((member) => member.userId));
  const resolved = resolveMentions(body, members);
  return [
    ...new Set([
      ...resolved,
      ...clientProvided.filter((id) => memberIds.has(id)),
    ]),
  ];
}

